`timescale 1ns/1ps
module tb_two_phase_handshake;
    reg clk;
    reg rst_n;
    reg s_valid;
    wire s_ready;
    reg [7:0] s_data;
    wire m_valid;
    reg m_ready;
    wire [7:0] m_data;

    two_phase_handshake dut (
        .clk(clk),
        .rst_n(rst_n),
        .s_valid(s_valid),
        .s_ready(s_ready),
        .s_data(s_data),
        .m_valid(m_valid),
        .m_ready(m_ready),
        .m_data(m_data)
    );

    always #5 clk = ~clk;

    initial begin
        #20000;
        $display("FAIL: Simulation watchdog timeout (Handshake stall/hang)");
        $fatal(1);
    end

    reg [7:0] sent_data [0:99];
    reg [7:0] recv_data [0:99];
    integer send_idx, recv_idx;

    always @(posedge clk) begin
        if (rst_n) begin
            if (m_valid && m_ready) begin
                recv_data[recv_idx] <= m_data;
                recv_idx <= recv_idx + 1;
            end
        end
    end

    initial begin
        clk = 0;
        rst_n = 0;
        s_valid = 0;
        s_data = 0;
        m_ready = 1;
        send_idx = 0;
        recv_idx = 0;
        #20;
        rst_n = 1;
        #10;

        while (send_idx < 50) begin
            @(posedge clk);
            s_valid = $random % 2;
            s_data = send_idx + 8'h20;
            m_ready = $random % 2;
            if (s_valid && s_ready) begin
                sent_data[send_idx] = s_data;
                send_idx = send_idx + 1;
            end
        end

        @(posedge clk);
        s_valid = 0;
        m_ready = 1;
        while (recv_idx < send_idx) @(posedge clk);

        #1;
        for (integer i = 0; i < 50; i = i + 1) begin
            if (sent_data[i] !== recv_data[i]) begin
                $display("FAIL: Data mismatch at %0d: sent %h, got %h", i, sent_data[i], recv_data[i]);
                $fatal(1);
            end
        end

        $display("ALL_TESTS_PASSED");
        $finish;
    end
endmodule
